# -*- coding: utf-8 -*-
# P3 Tư vấn sếp/khách. ok = đáp án đúng (lịch sự, kiên định, giải pháp chính đạo kèm con số); bad = 3 phương án sai.
# Số liệu là ví dụ giả định. Đáp án nhiễu cố ý dài/chi tiết tương đương đáp án đúng (sai ở NỘI DUNG, không ở độ dài).
P3 = [
dict(tag="Sếp đòi đánh giá 5 sao giả", tag_en="Boss asks for fake reviews", refs=["sp","shopee","law"], lvl="ta",
passage="Sếp Hải (chủ shop “Nhà Gọn”): “Tuần sau shop chạy sale lớn mà mới có 40 đánh giá. Em nhờ vài bạn viết khoảng 30 cái 5 sao cho nhanh đi, cứ nói giao nhanh đóng gói đẹp. Ai cũng làm vậy mà.”",
stem="Bạn trả lời sếp thế nào cho đúng nhất?",
ok="“Dạ anh, nếu Shopee phát hiện đánh giá viết hộ thì shop có thể bị gỡ đánh giá và phạt gian hàng, khách mới cũng khó tin. Em đề xuất nhắn 300 khách cũ mời đánh giá thật; nếu 10% phản hồi sẽ có khoảng 30 đánh giá thật trong 1–2 tuần.”",
bad=["“Dạ vâng, em nhờ vài bạn trong shop viết 30 cái 5 sao như anh nói, nội dung dặn giao nhanh, đóng gói đẹp. Sale lớn mà chỉ có 40 đánh giá thì khó cạnh tranh, em nghĩ lần này làm tạm một lần rồi sau này mình làm đúng cách ạ.”","“Không được anh ơi, làm vậy là lừa đảo, em không làm. Anh tự tìm người khác đi, em không tham gia vào chuyện sai trái như thế này và em cũng khuyên anh đừng làm nữa kẻo gặp rắc rối với khách ạ.”","“Em viết khoảng 10 cái thôi cho đỡ nhiều, chừng đó thì không sao anh, vì 10 cái so với 40 cái hiện có chỉ là một phần nhỏ. Phần còn lại em sẽ mời khách cũ đánh giá thật, vậy là vừa có vừa không phải làm quá.”"],
explain="Câu trả lời đúng làm 3 việc: nói rủi ro bằng ngôn ngữ lịch sự (gỡ đánh giá, phạt gian hàng, mất tin cậy), không buộc tội sếp, và đưa ngay giải pháp chính đạo có con số (300 khách cũ × 10% ≈ 30 đánh giá thật, ví dụ giả định). Cách “viết ít hơn” vẫn là đánh giá giả, chỉ nhỏ hơn; cách “làm tạm một lần” cũng vậy. Cách từ chối cộc lốc đúng về nguyên tắc nhưng không giúp sếp đạt mục tiêu nên khó được nghe lần sau. Kiểm tra lại quy định từng sàn về đánh giá mới nhất.",
en="Politely explain the risk, avoid accusing the boss and offer a real alternative with numbers: invite 300 past customers and expect about 30 genuine reviews (illustrative numbers)."),

dict(tag="Sếp đòi đồng hồ đếm ngược tự reset", tag_en="Boss asks for a fake countdown", refs=["sp","law"], lvl="ta",
passage="Sếp Dũng: “Landing page mình thêm cái đồng hồ 10 phút đi, hết giờ thì tự chạy lại. Khách thấy sắp hết giờ sẽ chốt nhanh, tỉ lệ chuyển đổi tăng rõ.”",
stem="Cách tư vấn nào vừa đúng đạo đức vừa giúp sếp bán được?",
ok="“Dạ anh, đồng hồ tự chạy lại là khuyến mãi giả, khách phát hiện sẽ mất tin và có thể khiếu nại. Mình đổi thành ưu đãi hạn thật: ‘Giảm 15% đến 23h59 Chủ nhật’ kèm 50 quà tặng có thật, rồi đo A/B 2 tuần.”",
bad=["“Dạ được anh, em làm đồng hồ 10 phút chạy lại sau mỗi lần tải trang như anh nói, rồi thêm một ghi chú nhỏ ở cuối trang là ‘ưu đãi có thể thay đổi’. Vừa tăng chốt đơn vừa có ghi chú, em nghĩ khá an toàn ạ.”","“Em thấy đồng hồ nào cũng là chiêu lừa, nên em sẽ không đặt đồng hồ hay hạn ưu đãi nào hết, mình chỉ đăng giá bình thường và chờ khách tự quyết định mua. Nếu doanh số chậm thì mình chấp nhận anh nhé.”","“Mình để đồng hồ 24 giờ cho lâu, ai mở lại trang sau đó thì hạn lại tính từ đầu, vì khách thường không nhớ mình đã vào lần trước. Như vậy chỉ là nhắc khách chứ không quá giả đâu anh nhỉ, vẫn tăng được tỉ lệ chốt đơn.”"],
explain="Đồng hồ thật gắn với hạn thật là cách thúc đẩy hợp lệ; đồng hồ lặp là giả. Đáp án đúng giữ mục tiêu của sếp (thúc mua) nhưng chuyển sang hạn thật, nêu hậu quả khiếu nại và đề xuất đo bằng A/B để sếp thấy kết quả, không chỉ nghe lý thuyết. Ghi chú nhỏ hay “nửa giả” không biến việc sai thành đúng. Các con số (15%, 50 quà, 2 tuần) là ví dụ giả định. Kiểm tra lại quy định quảng cáo mới nhất.",
en="A countdown tied to a real deadline is fine. Offer a real deadline plus a limited real bonus, and test it with an A/B test (illustrative numbers)."),

dict(tag="Khách đòi quảng cáo “chữa khỏi”", tag_en="Client wants cure claims", refs=["health","law"], lvl="ta",
passage="Chị Phương (chủ thương hiệu trà thảo mộc “An Nhiên”): “Em viết cho chị: ‘Uống 30 ngày hết tiểu đường, không cần thuốc’ nhé. Đối thủ họ viết còn mạnh hơn, mình không nói vậy sao bán được?”",
stem="Bạn trả lời khách hàng thế nào?",
ok="“Dạ chị, hứa ‘hết tiểu đường, bỏ thuốc’ rất nguy hiểm cho người bệnh và dễ bị gỡ quảng cáo, khóa tài khoản. Em đề xuất viết ‘Trà thảo mộc hỗ trợ lối sống lành mạnh; không phải là thuốc’ và thử 3 mẫu quảng cáo, mỗi mẫu 500.000đ trong 3 ngày.”",
bad=["“Dạ được, em viết đúng như chị yêu cầu, rồi thêm ảnh một bác sĩ cầm sản phẩm cho tăng uy tín. Đối thủ đã nói mạnh hơn thế thì mình nói như vậy cũng là cạnh tranh công bằng, em sẽ chạy thử với ngân sách nhỏ trước ạ.”","“Dạ em viết ‘giảm đường huyết rõ rệt sau 7 ngày, nhiều khách đã giảm liều thuốc’ cho nhẹ hơn một chút so với ‘hết tiểu đường’. Vậy vẫn đủ hấp dẫn mà chị không bị nói là hứa chữa bệnh, em nghĩ đây là cách dung hòa tốt ạ.”","“Dạ em xin lỗi chị, em không viết quảng cáo trà được vì sức khỏe là vấn đề rất nhạy cảm và em sợ rủi ro pháp lý. Chị nên tìm bên khác nhận việc này, hoặc chị tự viết nội dung rồi em chỉ làm phần thiết kế hình ảnh thôi ạ.”"],
explain="Với sản phẩm sức khỏe, lời hứa chữa bệnh và khuyên bỏ thuốc có thể làm hại người dùng và vi phạm quy định quảng cáo (kiểm tra lại bản mới nhất). Đáp án đúng nêu hậu quả, đổi sang lời nói đúng bản chất (hỗ trợ, không phải thuốc), và đưa kế hoạch thử cụ thể (3 mẫu × 500.000đ × 3 ngày, ví dụ giả định). “Giảm đường huyết rõ rệt” vẫn là hứa công dụng không chứng minh. Từ chối hoàn toàn thì bỏ lỡ cách làm đúng.",
en="Refuse cure claims, explain the risk, rewrite to 'supports a healthy lifestyle, not a medicine' and propose a small test budget (illustrative numbers)."),

dict(tag="Sếp đòi nhiều nick ảo để seeding", tag_en="Boss asks for fake accounts", refs=["fb","law"], lvl="ta",
passage="Sếp Lan: “Em lập 10 nick Facebook, vào các nhóm mẹ và bé, mỗi nick hỏi ‘ai dùng sữa Bé Khỏe chưa’, rồi nick khác trả lời khen. Nhóm thấy nhiều người khen sẽ tin thôi.”",
stem="Bạn đề xuất cách nào?",
ok="“Dạ chị, nick ảo mà bị lộ thì nhóm báo cáo và shop mất uy tín. Em đề xuất nhân viên đăng bằng tài khoản thật, nói rõ ‘mình làm ở Bé Khỏe’, mời 20 khách thật dùng thử và chia sẻ cảm nhận kể cả điểm chưa tốt.”",
bad=["“Dạ được chị, em lập 10 nick như chị yêu cầu, rồi chia nhau vào các nhóm mẹ và bé hỏi và trả lời khen sữa Bé Khỏe. Mục tiêu là có khoảng 30 lượt bình luận tích cực trong tuần đầu để nhóm thấy sản phẩm được quan tâm nhiều ạ.”","“Dạ em lập 3 nick thôi chị, vì 10 nick là nhiều quá so với ngân sách và thời gian của em. 3 nick khen cũng đủ để nhóm thấy có người quan tâm, mình thử trước rồi xem phản hồi ra sao mới tính tiếp ạ.”","“Em nghĩ mình không nên tham gia nhóm nào hết, vì các nhóm mẹ và bé rất khó tính và dễ phản ứng với quảng cáo. Mình cứ tập trung chạy quảng cáo trả tiền trên Facebook là đủ, khỏi cần nói chuyện với ai trong nhóm cho đỡ rắc rối ạ.”"],
explain="Seeding không sai nếu công khai danh tính; giấu danh tính bằng nick ảo là tà đạo. Đáp án đúng giữ ý tưởng “nói chuyện trong nhóm” nhưng chuyển sang công khai, mời 20 khách dùng thử thật chia sẻ cảm nhận (ví dụ giả định). Giảm số nick (3 thay vì 10) không đổi bản chất. Bỏ hẳn nhóm là phản ứng thái quá, bỏ qua cách làm chính đạo.",
en="Seeding is fine when disclosed. Use real accounts that state the relationship and invite 20 real customers to share honest feedback (illustrative numbers)."),

dict(tag="Khách muốn thổi phồng follower", tag_en="Client wants inflated followers", refs=["fb","tt","law"], lvl="ta",
passage="Anh Quân (chủ thương hiệu giày): “Trang mình mới có 2.000 follower, đối tác thấy ít không hợp tác. Em có cách nào kiếm thêm 50.000 follower trong tuần này không? Giá nào cũng được.”",
stem="Câu trả lời nào đúng nhất?",
ok="“Dạ anh, follower ảo thì tương tác thấp, đối tác kiểm tra sẽ nhận ra và nền tảng có thể xóa. Em đề xuất làm 8 video ngắn trong 4 tuần, chạy thử quảng cáo 1.000.000đ/tuần; mục tiêu thực tế thêm 1.000–2.000 follower thật kèm báo cáo tương tác.”",
bad=["“Dạ được anh, em sẽ tìm một dịch vụ tăng follower để nâng trang lên mức đối tác mong muốn ngay trong tuần này. Sau đó em báo cáo con số mới cho đối tác để họ yên tâm hợp tác, còn chi phí thì anh duyệt sau cũng được. Anh nói giá nào cũng được nên em chọn gói lớn nhất để chắc chắn đạt mốc trong tuần ạ.”","“Em sẽ tăng follower lên mức cao nhưng chỉ khoe con số đó cho vài đối tác lớn, còn khách hàng thì mình không cho thấy trên trang. Như vậy khách không bị ảnh hưởng, còn đối tác thì thấy trang đủ lớn để làm việc cùng ạ.”","“Em không làm được gì cho anh cả, trang chỉ có 2.000 follower thì rất khó hợp tác với đối tác lớn. Anh nên chờ vài tháng cho trang tự lớn lên rồi mình liên hệ lại, bây giờ có cố gắng cũng không có kết quả đâu ạ.”"],
explain="Con số follower ảo đánh lừa đối tác, dễ bị phát hiện qua tương tác thấp, và có thể bị xóa. Đáp án đúng đề xuất kế hoạch thật (8 video, 1.000.000đ/tuần) với mục tiêu khiêm tốn có thể đạt, và đổi thước đo sang tương tác thật. Khoe riêng cho đối tác vẫn là lừa đối tác. Nói “không làm được” bỏ mặc khách hàng. Số liệu mục tiêu là ví dụ giả định.",
en="Inflated followers are easy to detect and deceive partners. Propose a realistic organic plan: short videos, small ad budget and an engagement report."),

dict(tag="Sếp đòi bôi nhọ đối thủ", tag_en="Boss asks to smear a rival", refs=["fb","law"], lvl="ta",
passage="Sếp Tuấn (chủ quán cà phê “Hạt Nhỏ”): “Quán bên kia đường cướp khách mình. Em tạo bài trong nhóm khu phố nói họ dùng cà phê pha trộn, ảnh em tìm trên mạng cho giống thật nhé.”",
stem="Bạn nên nói gì với sếp?",
ok="“Dạ sếp, viết không có bằng chứng thì quán kia có thể kiện và mình mất uy tín. Em đề xuất đăng bài ‘Hạt Nhỏ rang xay tại quán’, tặng đồ uống mini cho 50 khách cuối tuần và mời họ đánh giá thật; nếu 20% quay lại là thêm 10 khách.”",
bad=["“Dạ được sếp, em đăng ngay trong nhóm khu phố, kèm ảnh em tìm trên mạng. Em nghĩ vài bài trong nhóm khu phố là đủ để khách chuyển sang quán mình ngay trong tuần này ạ.”","“Em đăng nhưng ghi ‘nghe nói’ và ‘chưa kiểm chứng’, sếp ạ. Mình chỉ chia sẻ lại điều người ta đồn, mà khách vẫn tránh quán đó, vừa nhanh vừa hiệu quả.”","“Mình nên bỏ qua quán kia, em không làm marketing cạnh tranh trực tiếp. Quán cứ giữ giá và chất lượng như hiện nay, khách thích thì sẽ quay lại; em chỉ làm vài bài giới thiệu chung chung rồi chờ xem doanh thu tháng sau thế nào ạ.”"],
explain="Tung tin sai về đối thủ là vô căn cứ và có thể bị kiện (kiểm tra lại quy định mới nhất); thêm chữ “nghe nói” không biến nó thành đúng. Cạnh tranh chính đạo là nói về điểm mạnh thật của mình. Đáp án đúng đưa kế hoạch cụ thể (50 khách, 20% quay lại = 10 khách) là ví dụ giả định để sếp thấy lợi ích. Bỏ qua cạnh tranh thì không giải quyết nỗi lo của sếp.",
en="Do not post unproven claims. Promote your own roastery process and invite 50 customers to a tasting; a 20% return rate would bring 10 repeat customers."),

dict(tag="Sếp đòi giá gốc ảo", tag_en="Boss wants an inflated original price", refs=["sp","law"], lvl="ta",
passage="Sếp Mai: “Cái áo này bán 399.000đ nhưng em ghi giá gốc 799.000đ rồi giảm 50% nhé, khách thấy giảm sâu sẽ mua. Giá 799.000đ mình chưa bán bao giờ, kệ.”",
stem="Cách phản hồi nào vừa kiên định vừa hữu ích?",
ok="“Dạ chị, giá 799.000đ chưa từng bán là giá gốc ảo, có thể bị khiếu nại hoặc gỡ quảng cáo. Em đề xuất ghi giá thường 399.000đ, giảm 15% còn 339.000đ trong 3 ngày thật, hoặc tặng tất trị giá 30.000đ; em theo dõi số đơn 3 ngày để chị so sánh.”",
bad=["“Dạ được chị, em ghi giá gốc 799.000đ rồi cho giảm 50% còn 399.000đ luôn. Khách thấy giảm sâu như vậy sẽ chốt nhanh, còn giá 799.000đ chưa từng bán thì em để đó, sau này chắc cũng không ai kiểm tra lại đâu chị ạ.”","“Em ghi giá gốc 599.000đ cho ‘nhẹ’ hơn 799.000đ, chưa bán bao giờ nhưng không quá xa giá thật 399.000đ. Mức giảm 33% nhìn vẫn hấp dẫn mà không quá phóng đại, em nghĩ chị sẽ thấy hợp lý hơn con số ban đầu ạ.”","“Em nghĩ chị nên bỏ hết giảm giá, giữ giá 399.000đ cố định quanh năm cho an toàn. Khách thấy giá ổn định sẽ tin shop hơn, còn quà tặng hay ưu đãi nhỏ thì không cần vì dễ bị hiểu nhầm là giảm giá ảo ạ.”"],
explain="Giá gốc phải là mức đã bán thật; “gốc ảo” dù cao hay thấp đều đánh lừa mức giảm. Đáp án đúng giữ ưu đãi nhưng chuyển sang mức giảm thật (15% còn 339.000đ) hoặc quà tặng, và hẹn đo kết quả (ví dụ giả định). Bỏ giảm giá hoàn toàn là cực đoan khi có thể làm ưu đãi hợp lệ. Kiểm tra lại quy định quảng cáo mới nhất.",
en="Only compare to prices actually charged. Offer a real 15% discount (339,000 VND) or a bonus gift and track the orders (illustrative numbers)."),

dict(tag="Sếp đòi ẩn đánh giá xấu", tag_en="Boss wants bad reviews hidden", refs=["sp","shopee","law"], lvl="xam",
passage="Sếp Khoa: “Cứ thấy đánh giá 1–3 sao là em báo cáo cho sàn xóa hoặc nhắn khách xin xóa, mình giữ điểm 4,8 cho đẹp. Khách chê nặng thì nhắn xin họ xóa giúp, năn nỉ vài lần là họ xóa.”",
stem="Bạn khuyên thế nào?",
ok="“Dạ anh, báo cáo vô lý hay thúc khách xóa có thể bị Shopee phạt, còn điểm toàn 5 sao khách cũng dễ nghi. Em đề xuất trả lời công khai từng đánh giá thấp trong 24 giờ, đổi trả khi lỗi thật và gom 3 lỗi hay gặp để sửa.”",
bad=["“Dạ được anh, em nhắn khách xin xóa và gửi 20.000đ cho từng người đồng ý. Mỗi đánh giá thấp xóa được thì điểm lên thêm một chút, chi phí cũng nhỏ so với doanh thu của đợt sale tuần tới nên em nghĩ rất đáng. Em sẽ soạn sẵn một tin nhắn mẫu để gửi cho nhanh ạ.”","“Em chỉ báo cáo những đánh giá xấu nhất để sàn xóa, những cái còn lại em để yên cho tự nhiên. Mình giữ điểm 4,8 mà không mất đồng nào, và khách cũng chỉ thấy những đánh giá ít gay gắt thôi anh ạ.”","“Mình bỏ tính năng đánh giá luôn cho khỏi lo, rồi chuyển sang quảng cáo bằng video và ảnh khách đã mua. Khách không thấy đánh giá thấp thì không bị ảnh hưởng, em nghĩ cách này sạch hơn việc cứ phải xóa từng cái ạ.”"],
explain="Xóa hoặc ép xóa đánh giá THẬT giấu sự thật khỏi người mua. Ranh giới rõ: xin khách xóa/báo cáo đánh giá thật chỉ vì chê là vùng xám; TRẢ TIỀN để xóa đánh giá thật là tà đạo (cùng cách gọi với câu “trượt dốc” trả 20.000đ để xóa). Đáp án đúng chuyển năng lượng sang xử lý nguyên nhân (trả lời 24 giờ, đổi trả khi lỗi thật, sửa 3 lỗi hay gặp) và báo cáo định kỳ. Báo cáo “chỉ những cái xấu nhất” vẫn là loại bỏ đánh giá thật. Tắt đánh giá thường không khả thi trên sàn. Các con số là ví dụ giả định.",
en="Do not pay for or push removal of genuine reviews (paying to remove genuine reviews crosses into deceptive territory). Reply publicly within 24 hours, fix real problems and report ratings weekly (illustrative numbers)."),

dict(tag="Khách muốn giấu phí vận chuyển và phụ thu", tag_en="Client wants hidden fees", refs=["sp","law"], lvl="xam",
passage="Chị Hạnh (chủ shop quà tặng): “Mình quảng cáo ‘Hộp quà 199.000đ’ cho hấp dẫn, còn phí gói quà 30.000đ và ship 25.000đ thì đến bước thanh toán mới hiện. Khách đã chọn rồi sẽ ngại bỏ.” Ở bước thanh toán, tổng tiền hiện rõ trước khi khách bấm trả và khách có thể thoát đơn dễ dàng.",
stem="Bạn tư vấn thế nào?",
ok="“Dạ chị, khách thấy giá tăng ở bước cuối thường bỏ giỏ và thấy bị lừa. Em đề xuất ghi ngay từ đầu ‘Hộp quà 199.000đ (đã gồm gói quà; ship từ 25.000đ)’ hoặc đặt giá trọn gói 239.000đ, rồi so tỉ lệ bỏ giỏ trước và sau 2 tuần.”",
bad=["“Dạ được chị, em ghi 199.000đ thật lớn và đẹp ở đầu trang, còn phí gói quà và phí ship thì ghi cỡ chữ nhỏ ở bước thanh toán. Khách đã chọn xong rồi thì ít khi bỏ giỏ vì tiếc công, em nghĩ cách này tăng đơn nhiều ạ.”","“Em ghi ‘giá chưa bao gồm các khoản khác’ ở dòng cuối trang cho đúng quy định là đủ. Khách nào đọc kỹ thì biết, còn khách không đọc thì mình cũng đã báo rồi, em nghĩ không ai trách shop được đâu chị ạ.”","“Mình miễn phí ship và gói quà cho tất cả đơn, rồi vẫn giữ giá 199.000đ như quảng cáo. Như vậy không còn phí nào phải nói, khách thích, còn phần lỗ thì mình tính sau khi thấy doanh số tăng lên bao nhiêu chị ạ.”"],
explain="Giấu phí đến bước cuối là kỹ thuật làm khách phát hiện muộn. Đáp án đúng hiển thị tổng chi phí ngay từ đầu và đề xuất đo kết quả. Dòng “chưa bao gồm” ở cuối trang vẫn giấu. Miễn phí ship cho tất cả có thể làm shop lỗ và không phải lý do đưa ra. Vì sao ở đây là xám chứ không phải tà như ca ứng dụng “dùng thử 0đ” (giấu phí chữ nhỏ, nút từ chối mỉa mai, hủy khó, không nhắc trước = tà đạo): ở đây phí vẫn hiện trước khi khách trả tiền và khách thoát đơn dễ dàng; nếu phí chỉ lộ SAU khi đã thanh toán hoặc không thể hủy đơn thì thành tà đạo. Số liệu là ví dụ giả định; quy định về hiển thị giá cần kiểm tra lại bản mới nhất.",
en="Show the full price early. Include gift wrap in the price or show 'ship from 25,000 VND' up front, then compare cart abandonment. Unlike the '0 VND trial' trap (tiny-print fee, shaming button, hard cancellation), the fee here is still shown before payment, so it is grey rather than deceptive (illustrative numbers)."),

dict(tag="Sếp đòi dùng ảnh khách không xin phép", tag_en="Boss wants to use customer photos without asking", refs=["fb","law"], lvl="xam",
passage="Sếp Vy (chủ tiệm hoa “Vườn Nhỏ”): “Em lấy ảnh bó hoa khách đăng Instagram làm quảng cáo trả phí nhé, khỏi hỏi, họ đăng công khai mà.”",
stem="Bạn nên làm gì?",
ok="“Dạ sếp, ảnh đăng công khai vẫn là của khách; dùng quảng cáo không hỏi dễ bị khiếu nại bản quyền. Em nhắn xin phép từng khách và ghi tên họ, tặng voucher 30.000đ không buộc điều kiện; nếu 15/30 khách đồng ý thì có 15 ảnh thật.”",
bad=["“Dạ được sếp, em lấy ảnh khách đăng công khai rồi cắt tên chủ ảnh và chạy quảng cáo luôn, vì ảnh đã công khai thì ai cũng dùng được. Nếu có khách phản đối thì em gỡ sau, như vậy tiết kiệm thời gian xin phép từng người cho tiệm ạ.”","“Em dùng ảnh nhưng chỉ chọn những người ít follower, vì họ ít để ý và ít khả năng phản ứng. Chọn khoảng 20 ảnh đẹp nhất để chạy quảng cáo trong tháng này là đủ, nếu có ai hỏi thì mình nhắn xin lỗi sau ạ.”","“Mình không dùng ảnh khách nữa, chỉ dùng ảnh tải về từ mạng cho các bó hoa tương tự cho đỡ phiền. Ảnh đẹp từ các trang chia sẻ ảnh thì chắc không ai khiếu nại, em sẽ chọn cho đúng phong cách của tiệm ạ.”"],
explain="Đăng công khai không có nghĩa cho phép dùng làm quảng cáo trả phí; dùng ảnh không hỏi là xám (kể cả khi vẫn ghi tên chủ ảnh). Ranh giới: CẮT TÊN chủ ảnh + không xin phép = tà đạo (che nguồn để khỏi bị phản ứng). Đáp án đúng xin phép, ghi tên và tặng quà không buộc điều kiện, kèm kế hoạch có con số (15/30, ví dụ giả định). Chọn người ít follower là cố ý lợi dụng người yếu thế. Ảnh tải trên mạng có thể vi phạm bản quyền hơn. Kiểm tra lại quy định bản quyền mới nhất.",
en="Public posts are still the customer's work. Ask permission, credit them and offer a no-strings gift: if 15 of 30 agree you have 15 real photos. Using photos without asking is grey; cropping out the name as well is deceptive (illustrative numbers)."),

dict(tag="Sếp đòi KOC nói dối “tự mua” và giấu quảng cáo", tag_en="Boss wants KOC to claim 'bought it myself'", refs=["tt","fb","law"], lvl="ta",
passage="Anh Long (chủ thương hiệu tai nghe): “Mình trả KOC 5.000.000đ làm video, nhưng đừng ghi ‘quảng cáo’, nhìn tự nhiên hơn. Cứ nói ‘mình tự mua’.”",
stem="Bạn phản hồi thế nào?",
ok="“Dạ anh, giấu quảng cáo và nói ‘tự mua’ là sai sự thật, video có thể bị gỡ và KOC mất uy tín. Em đề xuất ghi ‘Quảng cáo – được hãng gửi tặng’ ngay giây đầu, để KOC nói cả điểm trừ, rồi so với một video tự nhiên khác xem tỉ lệ bấm link thế nào.”",
bad=["“Dạ được anh, em dặn KOC nói là tự mua và bỏ hết hashtag quảng cáo, cho video nhìn tự nhiên như người dùng thật. Em nghĩ vậy khách sẽ tin hơn mà mình trả 5.000.000đ cho video cũng đáng đồng tiền ạ.”","“Em để ghi chữ quảng cáo ở cuối phần mô tả, như vậy là đủ theo quy định rồi anh. Video vẫn nhìn tự nhiên, còn mình cũng đã có ghi chú nếu sau này có ai hỏi tới ạ.”","“Mình không nên làm việc với KOC nữa, vì họ luôn phải ghi nhãn quảng cáo và khách sẽ ít tin hơn khi biết có trả tiền. Em đề xuất mình chuyển sang chạy quảng cáo bằng ảnh sản phẩm và vài bài viết của chính thương hiệu, vừa đỡ phải lo chuyện nhãn mác, vừa kiểm soát được nội dung ạ.”"],
explain="Nhãn quảng cáo phải ở nơi người xem thấy dễ; giấu nhãn đã là xám, còn CHỈ THỊ KOC nói dối “tự mua” (bịa trải nghiệm không có thật) là tà đạo, nên câu này xếp tà đạo. Đáp án đúng đề xuất đặt nhãn ngay đầu, cho KOC nói cả điểm trừ và có cách kiểm chứng bằng so sánh (ví dụ giả định). Ghi nhỏ ở cuối chưa đủ. Bỏ KOC là bỏ kênh hiệu quả. Kiểm tra lại quy định công bố quảng cáo mới nhất.",
en="Telling a creator to claim 'I bought it myself' is a lie, so this is deceptive. Label the ad at the very start and let the creator mention drawbacks; compare results with a non-labelled test if needed (illustrative numbers)."),

dict(tag="Sếp đòi gửi tin hàng loạt từ danh sách mua", tag_en="Boss wants mass messages from a bought list", refs=["zalo","law"], lvl="ta",
passage="Sếp Ngọc: “Anh mua được danh sách 10.000 số điện thoại người hay mua mỹ phẩm. Em nhắn Zalo/SMS hàng loạt giới thiệu sản phẩm mới, thêm link đặt hàng. Gửi 1 ngày 3 lần cho chắc.”",
stem="Bạn nên tư vấn gì?",
ok="“Dạ sếp, người nhận chưa đồng ý thì dễ bị báo spam, mất số gửi và có rủi ro về dữ liệu cá nhân. Em đề xuất nhắn tối đa 1–2 lần/tuần cho khách đã đồng ý, làm form đăng ký (tặng mã 30.000đ); 1.000 người xem form, 15% đăng ký là 150 người nhận tin.”",
bad=["“Dạ được sếp, em gửi 3 lần/ngày cho cả 10.000 số như sếp nói, vì nhắn càng nhiều thì càng có nhiều người bấm đặt hàng. Em sẽ làm tin ngắn gọn có link đặt hàng ngay để tăng đơn trong tuần đầu tiên ạ.”","“Em gửi 1 lần/ngày thôi và ghi rõ tên shop ở đầu tin cho người nhận khỏi thấy lạ. Có tên shop và ít tin hơn thì người ta đỡ khó chịu, em nghĩ như vậy là đủ lịch sự mà vẫn đến được cả 10.000 người ạ.”","“Em sẽ xin sếp mua thêm danh sách khác chất lượng hơn, ví dụ danh sách khách mua mỹ phẩm cao cấp gần đây. Danh sách tốt hơn thì tỉ lệ đặt hàng cũng cao hơn nhiều, em nghĩ đầu tư thêm cho phần này là đáng ạ, còn việc người nhận có đồng ý hay không thì mình tính sau.”"],
explain="Danh sách mua không có sự đồng ý của người nhận; giảm tần suất hay thêm tên shop vẫn không biến việc đó thành chính đạo. Đáp án đúng chuyển sang opt-in có động lực thật (mã 30.000đ) với kế hoạch cụ thể (1.000 × 15% = 150, ví dụ giả định). Cách “gửi 3 lần/ngày” và “mua danh sách khác” chỉ lặp lại cùng lỗi: không có sự đồng ý. Kiểm tra lại quy định tin nhắn và dữ liệu cá nhân mới nhất.",
en="A bought list means no consent. Build an opt-in list with a real incentive: 1,000 form viewers at 15% sign-up gives 150 quality contacts (illustrative numbers)."),
]
